# Let's try: Fill only frames that have complete borders (no broken corners/edges)
def frame_has_complete_border(tr, tc, size):
    """Check if all border cells are 2"""
    # Check top and bottom rows
    for c in range(tc, tc + size):
        if grid[tr][c] != 2:
            return False
        if grid[tr + size - 1][c] != 2:
            return False
    # Check left and right columns
    for r in range(tr, tr + size):
        if grid[r][tc] != 2:
            return False
        if grid[r][tc + size - 1] != 2:
            return False
    return True

