def edges_all_twos(tr, tc, size):
    for c in range(tc, tc + size):
        if grid[tr][c] != 2:
            return False
    for c in range(tc, tc + size):
        if grid[tr + size - 1][c] != 2:
            return False
    for r in range(tr, tr + size):
        if grid[r][tc] != 2:
            return False
    for r in range(tr, tr + size):
        if grid[r][tc + size - 1] != 2:
            return False
    return True

print("Edge completion check:")
for name, tr, tc, size in frame_configs:
    ok = edges_all_twos(tr, tc, size)
    print(f"{name}: {ok}")

